/* ParksMap — the 3D relief map of the lower 48 with every national park on it.
 *
 * Everything drawn is real data, generated by tools/build-parks.mjs:
 *   - the ground is a measured elevation grid (public/outdoors/us-relief.png), inked in
 *     flat bands with contour lines like a 1930s park screenprint
 *   - each light stands on a park's own National Park Service coordinate
 * ONE projection (`project`) places the ground and every light. lat first.
 *
 * The sun is the visitor's to move: one slider runs afternoon, golden hour, dusk, night.
 * It drives the light, the cast shadows, the sky and how hard the park lights burn. The
 * arc is a stylised west-setting sun for the whole map, not an almanac for any one place.
 *
 * The canvas is a view, not the only way in: the page's index reaches every park with a
 * 44px target and a keyboard, and carries the parks that sit off this canvas.
 */
import React, { useCallback, useEffect, useMemo, useRef, useState } from 'react'
import { Canvas, useFrame, useThree } from '@react-three/fiber'
import { OrbitControls, Html } from '@react-three/drei'
import { EffectComposer, Bloom, TiltShift2, Vignette, Noise } from '@react-three/postprocessing'
import * as THREE from 'three'
import { RELIEF } from './data/usRelief'

const W = 100
const { bounds, cols, rows } = RELIEF
const MID_LAT = (bounds.north + bounds.south) / 2
const ASPECT =
  ((bounds.east - bounds.west) * Math.cos((MID_LAT * Math.PI) / 180)) /
  (bounds.north - bounds.south)
const D = W / ASPECT
const RISE = 3.4 // world units at maxMetres: exaggerated so relief reads at continental scale
const BANDS = 16 // ink layers; spaced so lowlands get as many as the high country

export function inCanvas(park) {
  return (
    park.lng > bounds.west &&
    park.lng < bounds.east &&
    park.lat > bounds.south &&
    park.lat < bounds.north
  )
}

export function shortName(park) {
  return park.name.replace(/ National Parks?( (&|and) Preserve)?$| National and State Parks$/, '')
}

/** lat first. Returns [x, z] on the ground plane. */
export function project(lat, lng) {
  const x = ((lng - bounds.west) / (bounds.east - bounds.west)) * W - W / 2
  const z = ((bounds.north - lat) / (bounds.north - bounds.south)) * D - D / 2
  return [x, z]
}

/* ---------- the relief grid ---------- */
function useRelief() {
  const [relief, setRelief] = useState(null)
  useEffect(() => {
    let live = true
    const img = new window.Image()
    img.onload = () => {
      if (!live) return
      const c = document.createElement('canvas')
      c.width = cols
      c.height = rows
      const g = c.getContext('2d', { willReadFrequently: true })
      g.drawImage(img, 0, 0)
      const px = g.getImageData(0, 0, cols, rows).data
      const height = new Uint8Array(cols * rows)
      const land = new Uint8Array(cols * rows)
      for (let i = 0; i < cols * rows; i++) {
        height[i] = px[i * 4]
        land[i] = px[i * 4 + 1] > 50 && px[i * 4 + 1] < 150 ? 1 : 0 // the United States only
      }
      const groundAt = (lat, lng) => {
        const cx = Math.round(((lng - bounds.west) / (bounds.east - bounds.west)) * (cols - 1))
        const ry = Math.round(((bounds.north - lat) / (bounds.north - bounds.south)) * (rows - 1))
        const i = Math.max(0, Math.min(rows - 1, ry)) * cols + Math.max(0, Math.min(cols - 1, cx))
        return (height[i] / 255) * RISE
      }
      setRelief({ height, land, groundAt })
    }
    img.src = RELIEF.src
    return () => {
      live = false
    }
  }, [])
  return relief
}

/* ---------- the ink ---------- */
/* Dusk Field Guide palette, exclusive to /outdoors. Stops are in band space (0 = sea level). */
const INK = [
  [0.0, '#1F3A2C'],
  [0.1, '#2F5239'],
  [0.22, '#4E7148'],
  [0.36, '#7C8A52'],
  [0.5, '#A8794B'],
  [0.64, '#BF8A58'],
  [0.8, '#D8BC90'],
  [1.0, '#F3EAD6'],
].map(([t, hex]) => [t, new THREE.Color(hex)])

function useRamp() {
  return useMemo(() => {
    const n = 128
    const data = new Uint8Array(n * 4)
    const c = new THREE.Color()
    for (let i = 0; i < n; i++) {
      const t = i / (n - 1)
      let k = 1
      while (k < INK.length - 1 && t > INK[k][0]) k++
      const [t0, c0] = INK[k - 1]
      const [t1, c1] = INK[k]
      c.copy(c0).lerp(c1, Math.min(1, Math.max(0, (t - t0) / (t1 - t0))))
      c.convertLinearToSRGB()
      data[i * 4] = Math.round(c.r * 255)
      data[i * 4 + 1] = Math.round(c.g * 255)
      data[i * 4 + 2] = Math.round(c.b * 255)
      data[i * 4 + 3] = 255
    }
    const tex = new THREE.DataTexture(data, n, 1, THREE.RGBAFormat)
    tex.colorSpace = THREE.SRGBColorSpace
    tex.minFilter = tex.magFilter = THREE.LinearFilter
    tex.needsUpdate = true
    return tex
  }, [])
}

function useTerrain(relief, step) {
  return useMemo(() => {
    const nc = Math.floor((cols - 1) / step) + 1
    const nr = Math.floor((rows - 1) / step) + 1
    const pos = new Float32Array(nc * nr * 3)
    const elev = new Float32Array(nc * nr)
    const land = new Float32Array(nc * nr)
    for (let r = 0; r < nr; r++) {
      for (let c = 0; c < nc; c++) {
        const src = r * step * cols + c * step
        const i = r * nc + c
        const t = relief.height[src] / 255
        const isLand = relief.land[src] === 1
        pos[i * 3] = ((c * step) / (cols - 1)) * W - W / 2
        pos[i * 3 + 1] = isLand ? t * RISE : 0
        pos[i * 3 + 2] = ((r * step) / (rows - 1)) * D - D / 2
        elev[i] = isLand ? t : 0
        land[i] = isLand ? 1 : 0
      }
    }
    const idx = new Uint32Array((nc - 1) * (nr - 1) * 6)
    let k = 0
    for (let r = 0; r < nr - 1; r++) {
      for (let c = 0; c < nc - 1; c++) {
        const a = r * nc + c
        const b = a + 1
        const d = a + nc
        const e = d + 1
        // Only the United States is drawn: the country is a cut-out standing in the sky.
        if (land[a] + land[b] + land[d] + land[e] === 0) continue
        idx[k++] = a
        idx[k++] = d
        idx[k++] = b
        idx[k++] = b
        idx[k++] = d
        idx[k++] = e
      }
    }
    const g = new THREE.BufferGeometry()
    g.setAttribute('position', new THREE.BufferAttribute(pos, 3))
    g.setAttribute('aElev', new THREE.BufferAttribute(elev, 1))
    g.setAttribute('aLand', new THREE.BufferAttribute(land, 1))
    g.setIndex(new THREE.BufferAttribute(idx.subarray(0, k), 1))
    g.computeVertexNormals()
    return g
  }, [relief, step])
}

function Terrain({ relief, step, still }) {
  const geometry = useTerrain(relief, step)
  const ramp = useRamp()
  const ref = useRef()
  const t0 = useRef(null)
  const material = useMemo(() => {
    const m = new THREE.MeshStandardMaterial({ roughness: 1, metalness: 0, color: '#ffffff' })
    m.onBeforeCompile = (shader) => {
      shader.uniforms.uRamp = { value: ramp }
      shader.uniforms.uBands = { value: BANDS }
      shader.vertexShader = shader.vertexShader
        .replace(
          '#include <common>',
          '#include <common>\nattribute float aElev;\nattribute float aLand;\nvarying float vElev;\nvarying float vLand;'
        )
        .replace(
          '#include <begin_vertex>',
          '#include <begin_vertex>\nvElev = aElev;\nvLand = aLand;'
        )
      shader.fragmentShader = shader.fragmentShader
        .replace(
          '#include <common>',
          '#include <common>\nuniform sampler2D uRamp;\nuniform float uBands;\nvarying float vElev;\nvarying float vLand;'
        )
        .replace(
          '#include <color_fragment>',
          [
            '#include <color_fragment>',
            'if (vLand < 0.5) discard;', // interpolated, so the coast is a clean line
            'float e = pow(max(vElev, 0.0), 0.6) * uBands + 0.5;',
            'float band = floor(e) / uBands;',
            'vec3 ink = texture2D(uRamp, vec2(clamp(band, 0.004, 0.996), 0.5)).rgb;',
            'float f = fract(e);',
            'float w = max(fwidth(e), 0.00001);',
            'float line = 1.0 - smoothstep(w * 0.6, w * 1.6, min(f, 1.0 - f));',
            'diffuseColor.rgb = mix(ink, ink * 0.42, line * 0.5);',
          ].join('\n')
        )
    }
    return m
  }, [ramp])
  useFrame(({ clock }) => {
    if (!ref.current || still) return
    if (t0.current === null) t0.current = clock.elapsedTime
    const p = Math.min(1, (clock.elapsedTime - t0.current) / 2.2)
    ref.current.scale.y = 0.02 + 0.98 * (1 - Math.pow(1 - p, 3)) // the land rises, once
  })
  return (
    <mesh
      ref={ref}
      geometry={geometry}
      material={material}
      scale={[1, still ? 1 : 0.02, 1]}
      castShadow
      receiveShadow
    />
  )
}

/* ---------- the sun ---------- */
const hex = (h) => new THREE.Color(h)
/* s: 0 afternoon · 0.42 golden hour · 0.68 dusk · 1 night */
const KEYS = [
  {
    s: 0,
    el: 54,
    sun: hex('#FFF6E6'),
    sunI: 3.3,
    hemiSky: hex('#DCE9F5'),
    hemiGround: hex('#3A4A3F'),
    hemiI: 1.0,
    top: hex('#3A6CA6'),
    mid: hex('#86AED4'),
    low: hex('#D3E3EE'),
    glow: 0,
    glowY: 0.3,
    stars: 0,
    dark: 0,
  },
  {
    s: 0.42,
    el: 19,
    sun: hex('#FFCF94'),
    sunI: 3.1,
    hemiSky: hex('#B9C7DA'),
    hemiGround: hex('#1C2620'),
    hemiI: 0.72,
    top: hex('#1F3F68'),
    mid: hex('#6C7C98'),
    low: hex('#EDBB80'),
    glow: 0.85,
    glowY: 0.56,
    stars: 0,
    dark: 0.35,
  },
  {
    s: 0.68,
    el: 9,
    sun: hex('#FF9655'),
    sunI: 2.2,
    hemiSky: hex('#8497B8'),
    hemiGround: hex('#0F1714'),
    hemiI: 0.5,
    top: hex('#0A121D'),
    mid: hex('#1A2A42'),
    low: hex('#B5633C'),
    glow: 1,
    glowY: 0.64,
    stars: 0.25,
    dark: 0.8,
  },
  {
    s: 1,
    el: 9,
    sun: hex('#FF9655'),
    sunI: 0,
    hemiSky: hex('#5E78A8'),
    hemiGround: hex('#070B10'),
    hemiI: 0.34,
    top: hex('#04070D'),
    mid: hex('#0A1322'),
    low: hex('#131F33'),
    glow: 0,
    glowY: 0.7,
    stars: 1,
    dark: 1,
  },
]
const MOON = hex('#A9C1EA')

function atmosphere(s) {
  let i = 1
  while (i < KEYS.length - 1 && s > KEYS[i].s) i++
  const a = KEYS[i - 1]
  const b = KEYS[i]
  const t = Math.min(1, Math.max(0, (s - a.s) / (b.s - a.s)))
  const mix = (k) => a[k] + (b[k] - a[k]) * t
  const col = (k) => a[k].clone().lerp(b[k], t)
  const el = (mix('el') * Math.PI) / 180
  return {
    sunDir: new THREE.Vector3(-Math.cos(el) * 0.86, Math.sin(el), Math.cos(el) * 0.5).normalize(),
    sun: col('sun'),
    sunI: mix('sunI'),
    moonI: Math.max(0, (s - 0.74) / 0.26) * 0.85,
    hemiSky: col('hemiSky'),
    hemiGround: col('hemiGround'),
    hemiI: mix('hemiI'),
    top: col('top'),
    mid: col('mid'),
    low: col('low'),
    glow: mix('glow'),
    glowY: mix('glowY'),
    stars: mix('stars'),
    dark: mix('dark'),
  }
}
const phaseName = (s) =>
  s < 0.26 ? 'Afternoon' : s < 0.56 ? 'Golden hour' : s < 0.84 ? 'Dusk' : 'Night'

const STARS = (() => {
  // fixed pseudo-random field: decoration, the same every visit
  const out = []
  let seed = 7
  const rnd = () => ((seed = (seed * 16807) % 2147483647) - 1) / 2147483646
  for (let i = 0; i < 260; i++)
    out.push([rnd(), rnd() * 0.6, 0.4 + rnd() * 0.9, 0.35 + rnd() * 0.65])
  return out
})()

function makeSkyTexture() {
  const c = document.createElement('canvas')
  c.width = 512
  c.height = 512
  const t = new THREE.CanvasTexture(c)
  t.colorSpace = THREE.SRGBColorSpace
  return t
}

function Sky({ atmo }) {
  const [tex] = useState(makeSkyTexture)
  const live = useRef(null)
  useEffect(() => {
    if (!live.current) return
    const c = live.current.image
    const g = c.getContext('2d')
    const css = (col) => `#${col.getHexString()}`
    const ground = atmo.mid.clone().lerp(new THREE.Color('#0F1714'), 0.55 + atmo.dark * 0.45)
    const grad = g.createLinearGradient(0, 0, 0, 512)
    grad.addColorStop(0, css(atmo.top))
    grad.addColorStop(0.42, css(atmo.mid))
    grad.addColorStop(0.62, css(atmo.low))
    grad.addColorStop(0.8, css(ground))
    grad.addColorStop(1, '#0F1714')
    g.fillStyle = grad
    g.fillRect(0, 0, 512, 512)
    if (atmo.stars > 0.01) {
      for (const [x, y, r, a] of STARS) {
        g.fillStyle = `rgba(232,238,255,${(a * atmo.stars).toFixed(3)})`
        g.beginPath()
        g.arc(x * 512, y * 512, r, 0, Math.PI * 2)
        g.fill()
      }
    }
    if (atmo.glow > 0.01) {
      // the west is on the left of the map, so that is where the light goes down
      const cy = atmo.glowY * 512
      const rg = g.createRadialGradient(56, cy, 0, 56, cy, 420)
      rg.addColorStop(0, `rgba(255,214,150,${0.95 * atmo.glow})`)
      rg.addColorStop(0.16, `rgba(244,160,86,${0.7 * atmo.glow})`)
      rg.addColorStop(0.42, `rgba(170,96,84,${0.3 * atmo.glow})`)
      rg.addColorStop(1, 'rgba(120,80,90,0)')
      g.fillStyle = rg
      g.fillRect(0, 0, 512, 512)
    }
    live.current.needsUpdate = true
  }, [atmo])
  return <primitive ref={live} attach="background" object={tex} />
}

function SunLight({ atmo, coarse }) {
  const sun = useRef()
  const size = coarse ? 1024 : 2048
  useEffect(() => {
    if (!sun.current) return
    // never let the shadow-casting light drop so low that one ridge blacks out a state
    const dir = atmo.sunDir.clone()
    dir.y = Math.max(dir.y, 0.2)
    sun.current.position.copy(dir.normalize().multiplyScalar(160))
    sun.current.target.position.set(0, 0, 0)
    sun.current.target.updateMatrixWorld()
  }, [atmo])
  return (
    <>
      <hemisphereLight args={[atmo.hemiSky, atmo.hemiGround, atmo.hemiI]} />
      <directionalLight
        ref={sun}
        color={atmo.sun}
        intensity={atmo.sunI}
        castShadow
        shadow-mapSize={[size, size]}
        shadow-bias={-0.0006}
        shadow-normalBias={0.25}
      >
        <orthographicCamera attach="shadow-camera" args={[-58, 58, 36, -36, 20, 320]} />
      </directionalLight>
      <directionalLight position={[60, 80, 35]} color={MOON} intensity={atmo.moonI} />
    </>
  )
}

/* ---------- the park lights ---------- */
function useGlowTexture() {
  return useMemo(() => {
    const c = document.createElement('canvas')
    c.width = c.height = 128
    const g = c.getContext('2d')
    const grad = g.createRadialGradient(64, 64, 0, 64, 64, 64)
    grad.addColorStop(0, 'rgba(255,241,208,1)')
    grad.addColorStop(0.18, 'rgba(242,180,90,0.85)')
    grad.addColorStop(0.5, 'rgba(217,151,59,0.22)')
    grad.addColorStop(1, 'rgba(217,151,59,0)')
    g.fillStyle = grad
    g.fillRect(0, 0, 128, 128)
    const t = new THREE.CanvasTexture(c)
    t.colorSpace = THREE.SRGBColorSpace
    return t
  }, [])
}

const CORE_DAY = hex('#B5491A')
const CORE_NIGHT = hex('#FFE9BE')

/* A park is a campfire seen from far off: a hot point, a soft glow, a thread of light.
 * By day the glow fades and the point reads as a dark-red map mark instead. */
function Light({ park, index, active, hovered, still, glow, dark, groundAt }) {
  const [x, z] = project(park.lat, park.lng)
  const y = groundAt(park.lat, park.lng)
  const group = useRef()
  const halo = useRef()
  const t0 = useRef(null)
  const core = useMemo(() => new THREE.Color(), [])
  core
    .copy(CORE_DAY)
    .lerp(CORE_NIGHT, dark)
    .multiplyScalar(1 + dark * 2.2) // over 1.0 so it blooms
  useFrame(({ clock }) => {
    if (!group.current) return
    let s = 1
    if (!still) {
      if (t0.current === null) t0.current = clock.elapsedTime
      const p = Math.min(
        1,
        Math.max(0, (clock.elapsedTime - t0.current - 1.6 - index * 0.03) / 0.6)
      )
      s = 1 - Math.pow(1 - p, 3)
    }
    group.current.visible = s > 0.001
    group.current.scale.setScalar(Math.max(0.001, s))
    if (halo.current) {
      const base = (active ? 5 : hovered ? 3.4 : 2.1) * (0.55 + dark * 0.6)
      const breathe = still ? 0 : Math.sin(clock.elapsedTime * 1.4 + index) * 0.1
      const cur = halo.current.scale.x
      halo.current.scale.setScalar(cur + (base * (1 + breathe) - cur) * 0.15)
    }
  })
  const reach = active ? 4.4 : hovered ? 2.8 : 1.5
  return (
    <group position={[x, y, z]}>
      <group ref={group}>
        <mesh position={[0, reach / 2, 0]}>
          <cylinderGeometry args={[0.016, 0.045, reach, 6, 1, true]} />
          <meshBasicMaterial
            color={core}
            transparent
            opacity={active ? 0.95 : 0.6}
            depthWrite={false}
            toneMapped={false}
          />
        </mesh>
        <sprite ref={halo} position={[0, 0.22, 0]} scale={[2.1, 2.1, 1]}>
          <spriteMaterial
            map={glow}
            transparent
            opacity={0.25 + dark * 0.75}
            depthWrite={false}
            blending={THREE.AdditiveBlending}
            toneMapped={false}
          />
        </sprite>
        <mesh position={[0, 0.14, 0]}>
          <sphereGeometry args={[active ? 0.28 : 0.18, 14, 10]} />
          <meshBasicMaterial color={core} toneMapped={false} />
        </mesh>
      </group>
      {(hovered || active) && (
        <Html
          position={[0, reach + 0.7, 0]}
          center
          zIndexRange={[20, 0]}
          style={{ pointerEvents: 'none' }}
        >
          <span className={`parksmap-label${active ? ' is-active' : ''}`}>{shortName(park)}</span>
        </Html>
      )}
    </group>
  )
}

function Lights({ parks, selected, hover, still, dark, groundAt }) {
  const glow = useGlowTexture()
  return parks.map((p, i) => (
    <Light
      key={p.code}
      park={p}
      index={i}
      active={p.code === selected}
      hovered={p.code === hover}
      still={still}
      glow={glow}
      dark={dark}
      groundAt={groundAt}
    />
  ))
}

/* ---------- camera ---------- */
const HOME_DIR = new THREE.Vector3(0, 0.74, 0.67).normalize()
/** The home view. On a wide screen the country sits right of the title; on a tall one, under it. */
function homeView(camera, size) {
  const half = Math.tan((camera.fov * Math.PI) / 360)
  const aspect = size.width / size.height
  const wide = aspect > 1.25
  const share = wide ? 0.7 : 0.96 // how much of the width the country may take
  const dist = Math.max(W / (2 * half * aspect * share), (D * 1.45) / (2 * half))
  const visibleW = 2 * half * aspect * dist
  return { dist, x: wide ? -visibleW * 0.13 : 0, z: -dist * (wide ? 0.07 : 0.2) }
}

function Rig({ focus, still, coarse, groundAt }) {
  const controls = useRef()
  const { camera, size } = useThree()
  const want = useRef({
    target: new THREE.Vector3(),
    offset: new THREE.Vector3(),
    moving: true,
    first: true,
  })
  useEffect(() => {
    const w = want.current
    if (focus) {
      const [x, z] = project(focus.lat, focus.lng)
      w.target.set(x, groundAt(focus.lat, focus.lng), z)
      w.offset.set(0, 22, 22)
    } else {
      const home = homeView(camera, size)
      w.target.set(home.x, 0, home.z)
      w.offset.copy(HOME_DIR).multiplyScalar(home.dist)
    }
    w.moving = true
  }, [focus, camera, size, groundAt])
  useFrame(() => {
    const c = controls.current
    if (!c) return
    const w = want.current
    if (w.moving) {
      const k = still || w.first ? 1 : 0.065
      w.first = false
      c.target.lerp(w.target, k)
      const goal = w.target.clone().add(w.offset)
      camera.position.lerp(goal, k)
      if (camera.position.distanceTo(goal) < 0.05) w.moving = false
    }
    c.update()
  })
  return (
    <OrbitControls
      ref={controls}
      enabled={!coarse}
      enablePan={false}
      enableZoom={false} /* the page must keep its scroll wheel */
      enableDamping
      dampingFactor={0.08}
      minPolarAngle={0.35}
      maxPolarAngle={1.12}
      minAzimuthAngle={-0.6}
      maxAzimuthAngle={0.6}
      onStart={() => {
        want.current.moving = false
      }}
    />
  )
}

/* One picker for the whole canvas: the light nearest the pointer in SCREEN space wins.
 * Per-light hit meshes failed where parks cluster (a click on Yellowstone chose Grand
 * Teton, whose target stood in front of it). A drag never selects. */
function Picker({ parks, onHover, onSelect, groundAt }) {
  const { camera, gl, size } = useThree()
  useEffect(() => {
    const el = gl.domElement
    const v = new THREE.Vector3()
    const nearest = (e) => {
      const r = el.getBoundingClientRect()
      const px = e.clientX - r.left
      const py = e.clientY - r.top
      let best = null
      let bestD = 30
      for (const p of parks) {
        const [x, z] = project(p.lat, p.lng)
        const g = groundAt(p.lat, p.lng)
        for (const lift of [0.15, 0.8, 1.5]) {
          v.set(x, g + lift, z).project(camera)
          const d = Math.hypot(
            ((v.x + 1) / 2) * size.width - px,
            ((1 - v.y) / 2) * size.height - py
          )
          if (d < bestD) {
            bestD = d
            best = p.code
          }
        }
      }
      return best
    }
    let down = null
    const move = (e) => onHover(e.pointerType === 'touch' ? null : nearest(e))
    const leave = () => onHover(null)
    const press = (e) => {
      down = [e.clientX, e.clientY]
    }
    const release = (e) => {
      if (!down) return
      const dragged = Math.hypot(e.clientX - down[0], e.clientY - down[1]) > 6
      down = null
      if (dragged) return
      const hit = nearest(e)
      if (hit) onSelect(hit)
    }
    el.addEventListener('pointermove', move)
    el.addEventListener('pointerleave', leave)
    el.addEventListener('pointerdown', press)
    el.addEventListener('pointerup', release)
    return () => {
      el.removeEventListener('pointermove', move)
      el.removeEventListener('pointerleave', leave)
      el.removeEventListener('pointerdown', press)
      el.removeEventListener('pointerup', release)
    }
  }, [camera, gl, size, parks, onHover, onSelect, groundAt])
  return null
}

/* ?debug exposes each light's screen position so a browser test can click the real thing. */
function DebugProbe({ parks, groundAt }) {
  const { camera, size } = useThree()
  useEffect(() => {
    if (!/[?&]debug\b/.test(window.location.search)) return undefined
    window.__parksScreen = (code) => {
      const p = parks.find((q) => q.code === code)
      if (!p) return null
      const [x, z] = project(p.lat, p.lng)
      const v = new THREE.Vector3(x, groundAt(p.lat, p.lng) + 0.15, z).project(camera)
      return { x: ((v.x + 1) / 2) * size.width, y: ((1 - v.y) / 2) * size.height }
    }
    return () => {
      delete window.__parksScreen
    }
  }, [camera, size, parks, groundAt])
  return null
}

function canWebGL() {
  try {
    const c = document.createElement('canvas')
    return !!(c.getContext('webgl2') || c.getContext('webgl'))
  } catch {
    return false
  }
}

const DUSK = 0.66

export default function ParksMap({ parks, selected, onSelect, onDaylight }) {
  const relief = useRelief()
  const [hover, setHover] = useState(null)
  const [ok] = useState(canWebGL)
  const still = useMemo(
    () =>
      typeof window !== 'undefined' &&
      window.matchMedia('(prefers-reduced-motion: reduce)').matches,
    []
  )
  const coarse = useMemo(
    () => typeof window !== 'undefined' && window.matchMedia('(pointer: coarse)').matches,
    []
  )
  const [sun, setSun] = useState(still ? DUSK : 0.3)
  const touched = useRef(false)
  const onMap = useMemo(() => parks.filter(inCanvas), [parks])
  const focus = onMap.find((p) => p.code === selected) || null
  const atmo = useMemo(() => atmosphere(sun), [sun])

  // The one orchestrated moment: as the land rises, the afternoon runs down to dusk.
  useEffect(() => {
    if (still || !relief) return undefined
    let raf
    const t0 = window.performance.now()
    const tick = (now) => {
      if (touched.current) return
      const p = Math.min(1, Math.max(0, (now - t0 - 500) / 3200))
      setSun(0.3 + (DUSK - 0.3) * (1 - Math.pow(1 - p, 2)))
      if (p < 1) raf = window.requestAnimationFrame(tick)
    }
    raf = window.requestAnimationFrame(tick)
    return () => window.cancelAnimationFrame(raf)
  }, [still, relief])

  const bright = sun < 0.3
  useEffect(() => {
    if (onDaylight) onDaylight(bright)
  }, [bright, onDaylight])

  const moveSun = useCallback((e) => {
    touched.current = true
    setSun(Number(e.target.value) / 1000)
  }, [])

  if (!ok) {
    return (
      <div className="parksmap parksmap--flat" role="note">
        This device can&rsquo;t draw the 3D map. Every park is in the index below.
      </div>
    )
  }
  return (
    <div className={`parksmap${hover ? ' is-hovering' : ''}`}>
      <Canvas
        shadows
        dpr={[1, coarse ? 1.5 : 1.75]}
        camera={{ fov: 32, near: 1, far: 1200, position: [0, 90, 82] }}
        gl={{ antialias: true, powerPreference: 'high-performance' }}
        aria-label="Relief map of the lower 48 states with a light on every national park. The index below the map reaches every park."
        role="img"
      >
        <Sky atmo={atmo} />
        <SunLight atmo={atmo} coarse={coarse} />
        {relief && (
          <>
            <Terrain relief={relief} step={coarse ? 2 : 1} still={still} />
            <Lights
              parks={onMap}
              selected={selected}
              hover={hover}
              still={still}
              dark={atmo.dark}
              groundAt={relief.groundAt}
            />
            <Rig focus={focus} still={still} coarse={coarse} groundAt={relief.groundAt} />
            <Picker
              parks={onMap}
              onHover={setHover}
              onSelect={onSelect}
              groundAt={relief.groundAt}
            />
            <DebugProbe parks={onMap} groundAt={relief.groundAt} />
          </>
        )}
        {!coarse && (
          <EffectComposer multisampling={4}>
            <Bloom
              mipmapBlur
              luminanceThreshold={1.05}
              luminanceSmoothing={0.2}
              intensity={0.9}
              radius={0.7}
            />
            <TiltShift2 blur={0.1} />
            <Vignette offset={0.28} darkness={0.5} />
            <Noise opacity={0.035} />
          </EffectComposer>
        )}
      </Canvas>
      <label className="parksmap-sun">
        <span className="parksmap-sun-name">Move the sun</span>
        <input
          type="range"
          min="0"
          max="1000"
          step="1"
          value={Math.round(sun * 1000)}
          onChange={moveSun}
          aria-valuetext={phaseName(sun)}
        />
        <span className="parksmap-sun-now" aria-hidden="true">
          {phaseName(sun)}
        </span>
      </label>
    </div>
  )
}
